import teamJson from "@repo/team/team.json";

export const team = teamJson;
export const MEMBER_COLORS = ["#3D4F8C", "#0F7C80", "#E59A2B", "#C8553D"];

// Shared diagrams generated by assets/build_diagrams.js
const files = import.meta.glob("@repo/assets/diagrams/*.svg", { eager: true, query: "?url", import: "default" });
export const diagram = (name) => {
  const key = Object.keys(files).find((k) => k.endsWith(`/${name}.svg`));
  return key ? files[key] : "";
};
